<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeIsDefaultVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Holder\ThemeIsDefaultAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ThemeIsDefaultAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ThemeIsDefaultAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that isIsDefault returns null on a freshly created holder.
         */
        public function testIsDefaultNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithThemeIsDefaultAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isIsDefaultAssigned());
            $this->assertNull($holder->isIsDefault());
        }
}
class ImplWithThemeIsDefaultAttributeHolderUnitTest
{
  use ThemeIsDefaultAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedIsDefaultRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultIsDefault();
    }}
